  ('OTHER', 'passport', 'Biographic page of a valid passport, plus pages with U.S. visas and entry stamps.'),
  ('OTHER', 'resume', 'Current CV listing every position, dates, achievements, publications, awards and memberships.'),
  ('OTHER', 'status_docs', 'Documents showing your current U.S. status (I-797, I-20, EAD, DS-2019, as applicable).'),
  ('OTHER', 'i94', 'Most recent I-94 record (download from the CBP I-94 website).'),
  ('OTHER', 'degrees', 'Degree certificates or diplomas; add certified English translations where needed.'),
  ('OTHER', 'transcripts', 'Official academic transcripts (mark sheets) for each degree.'),
  ('OTHER', 'employment_letter', 'Employment verification letter on company letterhead.'),
  ('OTHER', 'offer_letter', 'Signed job offer with title, salary and start date.'),
  ('OTHER', 'recommendation_letters', 'Signed letters from experts on letterhead describing your work, its impact and how they know it.'),
  ('OTHER', 'additional', 'Anything else that supports your case.'))
UPDATE "visa_document_template_items" i
SET "instructions" = g.instructions, "updated_at" = now()
FROM "visa_document_templates" t, guidance g
WHERE i."template_id" = t."id" AND t."is_active" = true
  AND t."visa_type_code" = g.visa_type_code AND i."document_key" = g.document_key
  AND coalesce(trim(i."instructions"), '') = '';
